import{z as p,x as A,o as s,c as B,q as t,j as o,D as r,d as l,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const U=JSON.parse('{"title":"TPU 架构基本","description":"","frontmatter":{"title":"TPU 架构基本","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tpu-architecture-basics.md","filePath":"llm/tpu-architecture-basics.md","lastUpdated":1791413859000}'),d={name:"llm/tpu-architecture-basics.md"};function m(P,e,h,u,T,c){const E=A("Mermaid");return s(),B("div",null,[e[2]||(e[2]=t('<h1 id="tpu-架构基本" tabindex="-1">TPU 架构基本 <a class="header-anchor" href="#tpu-架构基本" aria-label="Permalink to &quot;TPU 架构基本&quot;">​</a></h1><div class="epigraph"><p>TPU 把矩阵乘收成脉动阵列，把片间通信收成 mesh。没有 CUDA warp，也没有 NCCL 这张表；集体是芯片上的邻接交换加编译器安排的副本。</p><footer>—— Jouppi 等 ISCA 2017 的第一代 TPU；后续 v2/v3/v4 公开论文与 Google 文档中的 mesh / ICI</footer></div><p><a href="/llm/cluster-fair-scheduling">上一课</a> 收在 NVIDIA 机群调度。本课打开「其他加速器」：生产上另一条已规模化的路是 TPU。缺口不是把 <a href="/llm/nvlink">NVLink</a> 翻译成新名词，而是 <strong>计算单元与互连从一开始就为稠密矩阵和同步副本设计</strong>。后课对照晶圆级、确定性 LPU 等；对比方法课会要求你用同一套屋顶线，而不是用 CUDA 生态当唯一坐标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一代 TPU 论文展示的是推理向的脉动阵列：权重驻留，激活流过，PCIe 连主机。到 v2 以后，训练需要 HBM、向量单元、以及芯片间互连（ICI），pod 内组成二维或更高维 mesh。程序员在 JAX / XLA 里看见的是 <code>device_mesh</code> 与分片标注（后来的 GSPMD），看不见 stream 与 NCCL 算法字符串。</p><p>问题是迁移：把 Megatron 的 TP/PP/DP 网格画到 TPU mesh 上，维必须嵌在 ICI 的邻接上，就像 GPU 的 TP 必须嵌在 NVLink 域。嵌错维，集体变成多跳转发，等效于在以太网做层内 All-Reduce。TPU 没有「先探拓扑再选 Ring/Tree」的运行时神话——编译器在编译期把集体降到邻接通信。错了就慢，而且往往在编译期就定死。</p><p><span class="marginnote">公开材料包括 Jouppi 等人的 TPU v1、v2/v3 pod、以及 v4 的光学电路交换等。本课只引用已发表结构，不填写未公开的某代峰值与未发布芯片代号的规格。</span></p><p><span class="marginnote">「脉动」借用心跳的意象：数据像血液一样以固定节拍在阵列里一波波推进，权重留在原地不动。每个小单元只做一件事——收上一对数、乘加、把结果递给下一个格子——整个阵列同时搏动，于是大批矩阵乘不需要反复去 HBM 取数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三块积木：MXU（矩阵乘单元 / 脉动阵列）、向量/标量单元（非 GEMM）、HBM。训练精度沿 BF16 / 较新的低精度格式走，和 GPU 的 Tensor Core 是同一类「稠密 GEMM 优先」，细节不同。互连：片上把核连起来，片间 ICI 成 mesh；更大规模用数据中心网络或公开描述过的光学交换把 pod 接起来。</p><p>并行：数据并行是沿 batch 维复制；模型并行是沿隐藏维切到相邻芯片。XLA 把 All-Reduce 做成沿 mesh 维的折叠。你要做的是把最密的通信放在 mesh 的短边，而不是在运行时拧 <code>NCCL_ALGO</code>。</p>',11)),(s(),o(n,null,{default:r(()=>[i(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22HBM%22%5D%20--%3E%20MXU%5B%22MXU%20%E8%84%89%E5%8A%A8%E9%98%B5%E5%88%97%22%5D%0A%20%20MXU%20--%3E%20V%5B%22%E5%90%91%E9%87%8F%E5%8D%95%E5%85%83%22%5D%0A%20%20C1%5B%22%E8%8A%AF%E7%89%87%22%5D%20---%7C%22ICI%22%7C%20C2%5B%22%E9%82%BB%E5%B1%85%E8%8A%AF%E7%89%87%22%5D%0A%20%20MESH%5B%22device%20mesh%22%5D%20--%3E%20SHARD%5B%22GSPMD%20%E5%88%86%E7%89%87%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"软件栈是 TPU 的一部分：XLA、JAX、部分 PyTorch/XLA。没有这一栈，硬件屋顶线到不了。对比 GPU 时必须把编译器成熟度算进去——后课对比方法会把它写成一维，而不是脚注。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},"「沿 mesh 维折叠 All-Reduce」可以理解成：把「全组同时开口对讲」拆成「沿一排邻居依次传话」，传一圈信息就齐了。编译器在编译期就把这条传话路线定死在物理相邻的芯片上，运行时没有换路线的余地——所以并行维的嵌入必须一开始就对。")],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,[l("脉动阵列让数据在 PE 间流动，减少对 HBM 的往返，算术强度高的 GEMM 吃满。小 kernel、控制密集、不规则稀疏，阵列利用率下降——这是和 GPU SIMT 不同的弱项。Mesh 上的集体延迟按跳数走，类似 "),a("a",{href:"/llm/dragonfly-torus"},"torus"),l(" 课的嵌入问题：逻辑维对齐物理维则 \\(\\alpha\\) 可接受；随机分片则每步多跳。")],-1)),(s(),o(n,null,{default:r(()=>[i(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%BF%80%E6%B4%BB%E4%BB%8E%E5%B7%A6%E4%BE%A7%E6%B5%81%E5%85%A5%20PE%20%E9%98%B5%E5%88%97%22%5D%20--%3E%20PE%5B%22%E6%AF%8F%E4%B8%AA%20PE%EF%BC%9A%E4%B9%98%E5%8A%A0%E4%B8%80%E6%AD%A5%EF%BC%8C%E7%BB%93%E6%9E%9C%E4%BC%A0%E5%8F%B3%E9%82%BB%22%5D%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E9%A9%BB%E7%95%99%E5%9C%A8%20PE%20%E5%86%85%E9%83%A8%22%5D%20--%3E%20PE%0A%20%20PE%20--%3E%20OUT%5B%22%E7%BB%93%E6%9E%9C%E6%B2%BF%E5%AF%B9%E8%A7%92%E7%BA%BF%E6%B5%81%E5%87%BA%E9%98%B5%E5%88%97%22%5D%0A%20%20OUT%20--%3E%20ACC%5B%22%E7%B4%AF%E5%8A%A0%E5%AE%8C%E6%88%90%E4%B8%80%E4%B8%AA%E7%9F%A9%E9%98%B5%E5%9D%97%22%5D%0A%20%20HBM%5B%22HBM%20%E5%8F%AA%E5%9C%A8%E5%A4%A7%E5%9D%97%E8%BF%9B%E5%87%BA%E6%97%B6%E5%8F%82%E4%B8%8E%22%5D%20--%3E%20A%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p>主机仍在：数据加载、检查点、编译。输入 pipeline 墙与 GPU 集群同类。TPU pod 的调度是 gang，且机型池更同质，碎片化模式不同，但「整 mesh 同时到齐」的约束更硬。</p><p><span class="marginnote"><a href="/llm/pretrain-comm">预训练通信</a> 的层次化 All-Reduce 在 TPU 上体现为「先沿某一 ICI 维 reduce 再沿另一维」。思想相同，实现不是 NCCL。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用某一代 GPU 的 TFLOPS 去除某一代 TPU 的 TFLOPS 当结论——存储层次、互连、精度、编译器全不同。不要假设 CUDA 核可以「稍改」跑上 MXU。不要把 Colossus / 内部未公开网络写进容量规划；只用公开 pod 结构。下一课 Cerebras 把「阵列」放大到晶圆，互连问题变成晶圆上的 2D mesh，而不是机柜 ICI。</p><p><span class="marginnote">常见误区：拿 GPU 峰值 TFLOPS 除以 TPU 峰值 TFLOPS 就说「谁快几倍」。两边的精度格式、HBM 带宽、编译器成熟度都不一样，峰值相除没有意义；正经比较要用同一套屋顶线——算术强度、带宽、通信半径——分别算出有效数字。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TPU：脉动矩阵单元 + HBM + 片间 mesh（ICI），集体由编译器降到邻接交换。</li><li>并行维必须嵌在 mesh 上，没有运行时 Ring/Tree 决策表可补救。</li><li>软件栈（XLA/JAX）是屋顶线的一部分。</li><li>不规则与小 kernel 是相对弱项；稠密 Transformer 训练是设计点。</li><li>出处：Jouppi 等 TPU 论文与 Google 公开的 pod / mesh 文档。</li></ul>',7))])}const D=p(d,[["render",m]]);export{U as __pageData,D as default};
